function shell(title,content){screen='COBRANÇAS';if(typeof active==='function')active('FINANCEIRO');root().innerHTML=css+`<main class="cb-page"><div class="cb-head">▣ COBRANÇAS${title==='NEGOCIAÇÕES'||title==='ROTAS DE COBRANÇA'||(!title&&content.includes('cb-c-id'))?'<button type="button" id="cb-shortcuts" class="cb-shortcut-top">⌂ ATALHOS</button>':''}</div>${title&&title!=='NEGOCIAÇÕES'&&title!=='ROTAS DE COBRANÇA'?`<div class="cb-caption"><strong>${title}</strong></div>`:''}${content}<div class="cb-actions"><button class="cb-btn red" id="cb-back">← VOLTAR</button></div><div id="cb-print" class="cb-print"></div></main>`;}

let histClient='',histFrom='',histTo='',histStatus='TODAS',histSearched=false,histDebt='';
function histDate(v){if(!v)return '';const x=String(v);return /^\d{4}-\d\d-\d\d/.test(x)?x.slice(0,10):''}
function histLate(p){const due=histDate(p.vencimento);return !!due&&due<today()}
function histAll(){const d=load();const linked=new Set([...(d.cartas||[]).flatMap(c=>c.titulos||[]),...(d.acordos||[]).flatMap(a=>a.titulos||[])] .map(String));return receivables().filter(p=>histDate(p.vencimento)&& (histLate(p)||linked.has(String(p.id))||p.dataPagamento&&histDate(p.dataPagamento)>histDate(p.vencimento)))}
function histDebtStatus(p){return saldo(p)<=0?'QUITADA':Number(p.pago||0)>0?'PARCIALMENTE PAGA':'EM ATRASO'}
function histDays(p){const date=histDate(p.vencimento);if(!date)return 0;const end=saldo(p)<=0?histDate(p.dataPagamento||p.pagamentoEm||p.dataBaixa)||today():today();return Math.max(0,Math.floor((Date.parse(end+'T12:00:00Z')-Date.parse(date+'T12:00:00Z'))/86400000))}
function histRelations(p){const d=load(),id=String(p.id),cs=(d.cartas||[]).filter(c=>(c.titulos||[]).some(v=>String(v)===id)),ns=(d.acordos||[]).filter(a=>(a.titulos||[]).some(v=>String(v)===id)),ids=new Set(cs.map(c=>String(c.id))),rs=(d.rotas||[]).flatMap(r=>(r.visitas||[]).filter(v=>ids.has(String(v.carta))).map(v=>({...v,rota:r.id,cobrador:r.cobradorNome,dataRota:r.data})));return {cs,ns,rs}}
function histDetail(p){const area=$('cb-h-detail');if(!area)return;if(!p){area.innerHTML='<div class="cb-panel"><h3>HISTÓRICO DA DÍVIDA</h3><p class="cb-muted">DÊ DOIS CLIQUES EM UMA DÍVIDA PARA VER O HISTÓRICO COMPLETO.</p></div>';return}const {cs,ns,rs}=histRelations(p),status=histDebtStatus(p),cliente=name(p);const entries=[{date:p.data||p.dataVenda||'',kind:'VENDA / BOLETO',detail:`DÍVIDA Nº ${e(p.id)} — ${e(p.descricao||'')} — VENCIMENTO ${fmt(p.vencimento)} — VALOR ${money(p.valor)}`}];for(const c of cs){entries.push({date:c.data,kind:'CARTA Nº '+c.id+' — '+(c.situacao||'PENDENTE'),detail:`COBRADOR: ${e(c.cobradorNome||'—')} — VALOR: ${money(c.total)}`});for(const h of c.historico||[])entries.push({date:h.data,kind:'CARTA Nº '+c.id+' — '+(h.acao||'AÇÃO'),detail:'USUÁRIO: '+e(h.usuario||'—')})}for(const a of ns){entries.push({date:a.data,kind:'NEGOCIAÇÃO Nº '+a.id,detail:`ORIGINAL: ${money(a.original)} | DESCONTO: ${money(a.desconto)} | ENTRADA: ${money(a.entrada)} | NEGOCIADO: ${money(a.total)} | SITUAÇÃO: ${e(a.situacao)}`});for(const h of a.historico||[])entries.push({date:h.data,kind:'NEGOCIAÇÃO Nº '+a.id+' — '+(h.acao||'AÇÃO'),detail:'USUÁRIO: '+e(h.usuario||'—')})}for(const v of rs)entries.push({date:v.dataRegistro||v.dataRota,kind:'ROTA Nº '+v.rota+' — CARTA Nº '+v.carta,detail:`${e(v.resultado||'SEM LANÇAMENTO')} | COBRADOR: ${e(v.cobrador||'—')} | RECEBEDOR: ${e(v.recebedorNome|| (v.resultado==='ENTREGUE NA CASA'?'DEIXADA NA CASA':'—'))} | ENDEREÇO: ${e(v.endereco||'—')} | OBS: ${e(v.observacoes||'—')} | USUÁRIO: ${e(v.usuarioRegistro||'—')}`});if(Number(p.pago||0)>0||saldo(p)===0)entries.push({date:p.dataPagamento||p.dataBaixa||'',kind:saldo(p)===0?'PAGAMENTO / QUITAÇÃO':'PAGAMENTO PARCIAL',detail:`PAGO: ${money(p.pago||Number(p.valor||0)-saldo(p))} | SALDO: ${money(saldo(p))}`});entries.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
const table=(head,rows,empty)=>`<div class="cb-table-wrap"><table class="cb-table"><thead><tr>${head.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${head.length}">${empty}</td></tr>`}</tbody></table></div>`;
area.innerHTML=`<section class="cb-panel cb-h-doc"><h3>HISTÓRICO DA DÍVIDA — Nº ${e(p.id)} <span style="float:right">${status}</span></h3><div class="cb-h-metrics"><div><small>CLIENTE</small><b>${e(cliente)}</b></div><div><small>VENCIMENTO</small><b>${fmt(p.vencimento)}</b></div><div><small>VALOR ORIGINAL</small><b>${money(p.valor)}</b></div><div><small>TOTAL PAGO</small><b>${money(p.pago||Number(p.valor||0)-saldo(p))}</b></div><div><small>SALDO DEVEDOR</small><b>${money(saldo(p))}</b></div><div><small>DIAS DE ATRASO</small><b>${histDays(p)}</b></div></div><h3>HISTÓRICO GERAL DA DÍVIDA</h3>${table(['DATA / HORA','MOVIMENTAÇÃO','DETALHES'],entries.map(x=>`<tr><td>${e(x.date?new Date(x.date).toLocaleString('pt-BR'): '—')}</td><td><b>${e(x.kind)}</b></td><td>${x.detail}</td></tr>`).join(''),'SEM MOVIMENTAÇÕES.')}<h3>CARTAS E ENTREGAS</h3>${table(['CARTA','ROTA','RESULTADO','RECEBEDOR','OBSERVAÇÕES'],rs.map(v=>`<tr><td>${e(v.carta)}</td><td>${e(v.rota)}</td><td>${e(v.resultado||'SEM LANÇAMENTO')}</td><td>${e(v.recebedorNome||'—')}</td><td>${e(v.observacoes||'—')}</td></tr>`).join(''),'NENHUMA VISITA REGISTRADA.')}<h3>NEGOCIAÇÕES</h3>${table(['Nº','DATA','DESCONTO','ENTRADA','NEGOCIADO','SITUAÇÃO'],ns.map(a=>`<tr><td>${e(a.id)}</td><td>${fmt(a.data)}</td><td>${money(a.desconto)}</td><td>${money(a.entrada)}</td><td>${money(a.total)}</td><td>${e(a.situacao)}</td></tr>`).join(''),'NENHUMA NEGOCIAÇÃO.')}<div class="cb-actions"><button class="cb-btn gray" id="cb-h-print">IMPRIMIR HISTÓRICO</button></div></section>`;
$('cb-h-print').onclick=()=>{const content=area.querySelector('.cb-h-doc').cloneNode(true);content.querySelector('.cb-actions')?.remove();const loja=typeof lojaAtual==='function'?lojaAtual():null;printDoc(`<div class="cb-doc"><h2>${e(loja?.nomeFantasia||loja?.nome||'LUCAS LIMA')} — HISTÓRICO DE COBRANÇAS</h2>${content.innerHTML}</div>`)};
}
function histRows(){const body=$('cb-h-rows');if(!body)return;const rows=histAll().filter(p=>(!histClient||String(p.pessoa)===histClient)&&(!histFrom||histDate(p.vencimento)>=histFrom)&&(!histTo||histDate(p.vencimento)<=histTo)&&(histStatus==='TODAS'||histDebtStatus(p)===histStatus));body.innerHTML=rows.map(p=>`<tr data-h-debt="${e(p.id)}" style="${String(p.id)===histDebt?'background:#dceaff':''}"><td>${e(p.conta||p.venda||p.id)}</td><td>${e(p.parcela||p.numeroParcela||'—')}</td><td>${fmt(p.vencimento)}</td><td>${money(p.valor)}</td><td>${money(saldo(p))}</td><td>${histDebtStatus(p)}</td></tr>`).join('')||'<tr><td colspan="6">NENHUMA DÍVIDA VENCIDA ENCONTRADA.</td></tr>';body.querySelectorAll('[data-h-debt]').forEach(tr=>tr.ondblclick=()=>{histDebt=tr.dataset.hDebt;histRows();histDetail(rows.find(p=>String(p.id)===histDebt))})}
function historyScreen(){shell('',`<div class="cb-h-layout"><div><section class="cb-panel"><h3>PESQUISA DO CLIENTE</h3><div class="cb-fields"><label>CLIENTE<div style="display:flex;gap:6px"><input id="cb-h-client" readonly placeholder="TODOS" value="${e(clientsList().find(c=>String(c.codigo)===histClient)?.nome||'TODOS')}"><button class="cb-btn green" id="cb-h-pick">+</button></div></label></div><div class="cb-fields" style="margin-top:10px"><label>DATA INICIAL<input type="date" id="cb-h-from" value="${histFrom}"></label><label>DATA FINAL<input type="date" id="cb-h-to" value="${histTo}"></label></div><div class="cb-fields" style="margin-top:10px"><label>SITUAÇÃO<select id="cb-h-status">${['TODAS','EM ATRASO','PARCIALMENTE PAGA','QUITADA'].map(x=>`<option ${x===histStatus?'selected':''}>${x}</option>`).join('')}</select></label><button class="cb-btn" id="cb-h-search">PESQUISAR</button></div></section><section class="cb-panel"><h3>DÍVIDAS — BOLETOS VENCIDOS</h3><div class="cb-table-wrap"><table class="cb-table"><thead><tr><th>VENDA</th><th>PARCELA</th><th>VENCIMENTO</th><th>VALOR</th><th>SALDO</th><th>SITUAÇÃO</th></tr></thead><tbody id="cb-h-rows"><tr><td colspan="6">CLIQUE EM PESQUISAR PARA EXIBIR AS DÍVIDAS.</td></tr></tbody></table></div><p class="cb-muted">DÊ DOIS CLIQUES NA DÍVIDA PARA ABRIR SEU HISTÓRICO.</p></section></div><div id="cb-h-detail"></div></div><div id="cb-h-modal" style="display:none;position:fixed;inset:0;background:#001b4288;z-index:999999;align-items:center;justify-content:center"><div style="background:white;padding:18px;border-radius:8px;width:min(570px,95vw)"><h3>SELECIONAR CLIENTE</h3><input id="cb-h-query" placeholder="PESQUISAR POR NOME OU CÓDIGO" style="width:100%;padding:10px"><div id="cb-h-options" style="max-height:300px;overflow:auto"></div><button class="cb-btn gray" id="cb-h-close">FECHAR</button></div></div>`);$('cb-back').onclick=menu;histDetail(null);$('cb-h-pick').onclick=()=>{const modal=$('cb-h-modal'),input=$('cb-h-query'),options=$('cb-h-options');modal.style.display='flex';input.value='';const render=()=>{const q=input.value.trim().toUpperCase();options.innerHTML='<button class="cb-btn gray" style="display:block;width:100%;margin:5px 0;text-align:left" id="cb-h-all">TODOS OS CLIENTES</button>'+clientsList().filter(c=>String(c.nome||'').toUpperCase().includes(q)||String(c.codigo||'').includes(q)).slice(0,50).map(c=>`<button class="cb-btn gray" style="display:block;width:100%;margin:5px 0;text-align:left" data-client="${e(c.codigo)}">${e(c.codigo)} — ${e(c.nome)}</button>`).join('')||'<p>NENHUM CLIENTE ENCONTRADO.</p>';$('cb-h-all').onclick=()=>{histClient='';$('cb-h-client').value='TODOS';modal.style.display='none';histSearched=false;$('cb-h-rows').innerHTML='<tr><td colspan="6">CLIQUE EM PESQUISAR PARA EXIBIR AS DÍVIDAS.</td></tr>';histDetail(null)};options.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>{histClient=b.dataset.client;$('cb-h-client').value=clientsList().find(c=>String(c.codigo)===histClient)?.nome||histClient;modal.style.display='none';histSearched=false;$('cb-h-rows').innerHTML='<tr><td colspan="6">CLIQUE EM PESQUISAR PARA EXIBIR AS DÍVIDAS.</td></tr>';histDetail(null)})};input.oninput=render;render();input.focus()};$('cb-h-close').onclick=()=>$('cb-h-modal').style.display='none';$('cb-h-search').onclick=()=>{histFrom=$('cb-h-from').value;histTo=$('cb-h-to').value;histStatus=$('cb-h-status').value;histSearched=true;histRows()};if(histSearched)histRows()}

function menu(){shell('CONTROLE DE COBRANÇAS',`<div class="cb-menu"><button class="cb-tile" id="cb-letter"><span class="cb-icon">▤</span><span><b>CARTA DE COBRANÇA</b><small>Consulte dívidas dos clientes e imprima cartas de cobrança.</small></span><b>›</b></button><button class="cb-tile" id="cb-neg"><span class="cb-icon">⇄</span><span><b>NEGOCIAÇÕES</b><small>Descontos, parcelamentos e carnês para entregar ao cliente.</small></span><b>›</b></button><button class="cb-tile" id="cb-route"><span class="cb-icon">⌖</span><span><b>ROTAS DE COBRANÇA</b><small>Organize visitas e distribua clientes aos cobradores.</small></span><b>›</b></button><button class="cb-tile" id="cb-history"><span class="cb-icon" style="background:#7440e6">◷</span><span><b>HISTÓRICO DE COBRANÇAS</b><small>Consulte dívidas vencidas, cartas, entregas, negociações e pagamentos.</small></span><b>›</b></button></div>`);[['cb-letter',letter],['cb-neg',negotiations],['cb-route',routes],['cb-history',historyScreen]].forEach(([id,fn])=>{const btn=$(id);if(btn){btn.type='button';btn.onclick=ev=>{ev.preventDefault();fn()};}});$('cb-back').onclick=()=>category('FINANCEIRO');}
function listDebts(q='',onlyOverdue=false){return receivables().filter(p=>saldo(p)>0&&(!onlyOverdue||p.vencimento<today())&&(!q||[p.id,p.conta,p.descricao,name(p)].some(v=>String(v||'').toUpperCase().includes(q.toUpperCase()))));}
function debtTable(rows,checkbox=true){return `<div class="cb-table-wrap"><table class="cb-table"><thead><tr>${checkbox?'<th>SELECIONAR</th>':''}<th>Nº</th><th>CLIENTE</th><th>DESCRIÇÃO</th><th>VENCIMENTO</th><th>VALOR</th><th>SALDO</th></tr></thead><tbody>${rows.map(p=>`<tr data-cb-id="${e(p.id)}">${checkbox?`<td><input class="cb-check" type="checkbox" data-id="${e(p.id)}" ${selected.has(String(p.id))?'checked':''}></td>`:''}<td>${e(p.id)}</td><td>${e(name(p))}</td><td>${e(p.descricao)}</td><td>${fmt(p.vencimento)}</td><td>${money(p.valor)}</td><td>${money(saldo(p))}</td></tr>`).join('')||`<tr><td colspan="${checkbox?7:6}">NENHUMA DÍVIDA ENCONTRADA.</td></tr>`}</tbody></table></div>`;}
function bindChecks(){document.querySelectorAll('.cb-check').forEach(x=>{x.onchange=()=>{x.checked?selected.add(x.dataset.id):selected.delete(x.dataset.id)};x.closest('tr').ondblclick=()=>{x.checked=!x.checked;x.onchange()}})}
function printDoc(html){$('cb-print').innerHTML=html;window.print()}
let cartaId=null,cartaCliente='',cartaCobrador='',cartaFiltros={inicio:'',fim:'',cliente:'TODOS'},cartaPesquisou=false;
