function cartaSelectClient(code){cartaCliente=String(code);selected=new Set();letter()}
function cartaSeletor(tipo){const pop=$('cb-c-modal');pop.style.display='flex';pop.hidden=false;const input=$('cb-c-modal-input'),options=$('cb-c-modal-list');input.value='';options.innerHTML='<p class="cb-muted">DIGITE PARA PESQUISAR.</p>';input.focus();const lista=tipo==='cobrador'?employeesList():clientsList();$('cb-c-modal-title').textContent=tipo==='cobrador'?'SELECIONAR COBRADOR':'SELECIONAR CLIENTE';input.oninput=()=>{const q=input.value.trim().toUpperCase();options.innerHTML=q?lista.filter(c=>String(c.nome||'').toUpperCase().includes(q)||String(c.codigo||'').includes(q)).slice(0,40).map(c=>`<button type="button" class="cb-btn gray" style="display:block;width:100%;text-align:left;margin:5px 0" data-code="${e(c.codigo||c.id)}">${e(c.codigo||c.id)} — ${e(c.nome)}</button>`).join('')||'<p>NENHUM REGISTRO ENCONTRADO.</p>':'<p class="cb-muted">DIGITE PARA PESQUISAR.</p>';options.querySelectorAll('[data-code]').forEach(btn=>btn.onclick=()=>{if(tipo==='cobrador'){cartaCobrador=btn.dataset.code;const f=employeesList().find(x=>String(x.codigo||x.id)===cartaCobrador);$('cb-c-agent').value=(f?.nome||cartaCobrador);$('cb-c-phone').value=collectorPhone(f)}else if(tipo==='filtro'){cartaFiltros.cliente=btn.dataset.code;$('cb-c-filter-client').value=clientsList().find(x=>String(x.codigo)===btn.dataset.code)?.nome||btn.dataset.code}else cartaSelectClient(btn.dataset.code);pop.style.display='none';pop.hidden=true})};};
